#include "raikou/mfem_pic_full_time.h"
#include <fstream>
#include <iostream>
#include <openssl/sha.h>
#include <sstream>
#include <iomanip>
namespace m=raikou::mfem_backend;
using J=m::ArenaJson;
int checks=0;J results=J::array();
void check(bool x,const char* name){++checks;results.push_back({{"name",name},{"passed",x}});if(!x)throw std::runtime_error(name);}
template<class F>void rejects(F f,const char* name){bool yes=false;try{f();}catch(const std::exception&){yes=true;}check(yes,name);}
std::string sha(std::string s){unsigned char b[32];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),b);std::ostringstream out;for(auto c:b)out<<std::hex<<std::setfill('0')<<std::setw(2)<<unsigned(c);return out.str();}
m::GapPicOptions options(){m::GapPicOptions o;o.nx=o.ny=45;o.width_m=o.gap_m=.009;o.depth_m=.025;o.finite_foils=true;o.finite_axial_extent=true;o.short_z_m=0;o.feed_z_m=.025;o.lower_foil={.002,.007,.0018,.002};o.upper_foil={.002,.007,.007,.0072};return o;}
std::vector<m::ArenaStateSpec> states(){return {{"e",0,0,-1,m::pic_me,0,0},{"n",2,1,0,2.9915e-26,0,0}};}
std::vector<m::ArenaChannel> channels(){return {{"conditional-storage-control","e","n",{"e","n"},sha("data"),sha("kernel"),sha("binding"),"manufactured-storage-control-only"}};}
m::FullTimeGenesisBinding genesis(){m::FullTimeGenesisBinding g;g.time_s=26.31715e-9;g.origin_provenance="manufactured/full-time-storage-control-no-simulation";g.field_sha256=sha("field");g.mesh_sha256=sha("mesh");g.material_sha256=sha("material");g.frame_sha256=sha("frame");g.common_clock_sha256=sha("initial-clock");g.heat_sha256=sha("heat");g.source_sha256=sha("source");g.rng_sha256=sha("chemistry-RNG-and-config");return g;}
auto fresh(){return m::PicArena::create_full_time(options(),states(),channels(),{{"electron","e","manufactured/source",{4,0},{.004,.004,.0125},{1e6,0,0}},{"neutral","n","manufactured/source",{8,0},{.00403,.004,.0125},{0,0,0}}},genesis());}
m::FullTimeStepBinding common(m::PicArena& a){const auto b=a.full_time_boundary();return {b->accepted_step,b->accepted_arena_revision,b->time_s,b->time_s+5e-15,5e-15,b->accepted_arena_sha256,b->field_sha256,b->mesh_sha256,b->material_sha256,sha("new-common")};}
m::ExposureBinding exposure(const m::FullTimeStepBinding& b){return {b,m::FullTimeSlot::before_transport,b.begin_s,.5*b.dt_s,0,b.accepted_field_sha256};}
m::ArenaStochasticCompletion completion(const m::ExposureBinding& b){const auto c=channels()[0];m::ArenaStochasticCompletion x;x.integration_owner_id="storage-control-owner";x.before_rng_clock_sha256=genesis().rng_sha256;x.after_rng_clock_sha256=sha("after-chemistry");x.common_clock_sha256=b.common.common_clock_sha256;x.channel_id=c.id;x.dataset_sha256=c.dataset_sha256;x.kernel_manifest_sha256=c.kernel_manifest_sha256;x.kernel_binding_file_sha256=c.kernel_binding_file_sha256;x.model=c.model;x.stage_sequence=b.owner_stage_sequence;x.frozen_physical_stage_s=b.frozen_physical_stage_s;x.common_interval_begin_s=b.common.begin_s;x.common_interval_end_s=b.common.end_s;return x;}
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("output path");const std::string dir=argv[1];auto a=fresh();const auto before=a->state_prefix();const auto snapshot=a->snapshot();const auto census=a->rate_population(8);check(a->full_time_boundary()->time_s==genesis().time_s,"authored full-time epoch exact");check(a->full_time_boundary()->authored_full_time_genesis,"genesis phase explicit");check(census.size()==2&&census[1].native.charge_C==0,"canonical neutral resident carrier");
  rejects([&]{a->prepare_transport(5e-15);},"legacy native DKD forbidden in total-field mode");rejects([&]{m::ArenaEvent e;a->prepare(e);},"legacy reaction placement forbidden in total-field mode");a->save(dir+"/genesis.json");auto restored=m::PicArena::restore_full_time(dir+"/genesis.json",options(),states(),channels(),*a->full_time_boundary());check(restored->state_prefix()==before,"fresh-process total-field genesis restart exact");auto mismatch=*a->full_time_boundary();mismatch.rng_sha256=sha("different RNG");rejects([&]{m::PicArena::restore_full_time(dir+"/genesis.json",options(),states(),channels(),mismatch);},"restart refuses foreign chemistry RNG owner seal");auto o=options();o.width_m=.018;rejects([&]{m::PicArena::restore_full_time(dir+"/genesis.json",o,states(),channels(),*a->full_time_boundary());},"restart refuses kinetic geometry mismatch");
  auto b=common(*a);auto bad=b;bad.accepted_arena_sha256=sha("foreign");rejects([&]{a->begin_full_time_step(bad,8,32);},"foreign accepted prefix refuses before private allocation");rejects([&]{a->begin_full_time_step(b,1,32);},"native census resource cap refuses");auto outer=a->begin_full_time_step(b,8,32);auto e=exposure(b);rejects([&]{outer.fork_transport_trial();},"transport before first exposure refuses");rejects([&]{outer.second_exposure(e);},"second before first exposure refuses");rejects([&]{outer.seal({});},"incomplete outer seal refuses");auto wrong=e;wrong.collision_duration_s=(b.end_s-b.begin_s)*.5;check(wrong.collision_duration_s!=e.collision_duration_s,"nonzero epoch detects subtraction-rounded duration");rejects([&]{outer.first_exposure(wrong);},"authoritative half duration enforced");auto scope=outer.first_exposure(e);auto phase=scope.phase();check(phase.kind==m::ArenaPhase::Kind::FullTimeEndpoint&&phase.physical_stage_s==b.begin_s,"new full-time endpoint phase explicit");const auto private_before=scope.state_prefix();
  rejects([&]{scope.prepare_compound_with_completion(1,[&](m::CollisionScope& s)->m::ArenaStochasticCompletion{check(a->state_prefix()==before&&a->snapshot()==snapshot,"accepted owner unchanged in private callback");check(s.state_prefix()==private_before,"private frame observed through only scoped handle");throw std::runtime_error("manufactured callback failure");});},"compound exception restores private frame");check(scope.state_prefix()==private_before&&a->state_prefix()==before,"failed callback leaves both prefixes unchanged");
  auto c=completion(e);auto wrongc=c;wrongc.common_clock_sha256=sha("foreign-clock");rejects([&]{scope.prepare_compound_with_completion(1,[&](auto&){return wrongc;});},"completion common clock mismatch refuses");wrongc=c;wrongc.stage_sequence=1;rejects([&]{scope.prepare_compound_with_completion(1,[&](auto&){return wrongc;});},"initial owner sequence must be zero");wrongc=c;wrongc.frozen_physical_stage_s=b.end_s;rejects([&]{scope.prepare_compound_with_completion(1,[&](auto&){return wrongc;});},"completion physical endpoint mismatch refuses");auto t=scope.prepare_compound_with_completion(1,[&](auto&){return c;});auto sibling=outer.first_exposure(e);check(!sibling.can_publish(t),"foreign scope cannot publish same-outer token");check(!a->can_publish(t),"private exposure token cannot publish accepted arena");check(scope.can_publish(t),"zero-event private completion preflight");const auto candidate=t.candidate_state_prefix();check(scope.try_publish(t),"zero-event private completion publishes privately");check(!scope.try_publish(t),"private completion double publish refuses");check(scope.state_prefix()==candidate,"completed scope prefix exactly equals token candidate prefix");check(a->state_prefix()==before&&a->snapshot()==snapshot,"completed first exposure leaves accepted state unchanged");auto trial=outer.fork_transport_trial();check(trial.native_census(8).size()==2,"transport census includes canonical neutral");check(trial.staged_arena_revision()==snapshot->revision+2,"transport revision includes outer and zero-event exposure");check(trial.state_prefix()==candidate,"transport starts exact completed first frame");m::FullTimeMotionBinding mb{b,sha("fake-motion"),b.accepted_field_sha256,sha("newfield"),sha("newheat"),genesis().source_sha256};std::vector<m::GapParticle> endpoints;for(const auto& n:trial.native_census(8))endpoints.push_back(n.native);rejects([&]{trial.prepare_total_field_motion(mb,endpoints,J::object());},"motion requires genuine sealed Hall record envelope");rejects([&]{trial.prepare_total_field_motion(mb,endpoints,J::object(),J::array({1}));},"closed fixture refuses unowned source mutations");rejects([&]{trial.prepare_total_field_motion(mb,endpoints,J::object(),J::array(),J::array({1}));},"closed fixture refuses unowned boundary mutations");check(a->state_prefix()==before&&a->snapshot()==snapshot,"failed motion leaves accepted state unchanged");a->save(dir+"/accepted-during-private.json");auto r=m::PicArena::restore_full_time(dir+"/accepted-during-private.json",options(),states(),channels(),*a->full_time_boundary());check(r->state_prefix()==before,"private trial is absent from accepted checkpoint");
  auto dying=fresh();auto deadouter=dying->begin_full_time_step(common(*dying),8,32);auto deadscope=deadouter.first_exposure(exposure(common(*dying)));auto deadc=completion(exposure(common(*dying)));auto deadtoken=deadscope.prepare_compound_with_completion(1,[&](auto&){return deadc;});dying.reset();check(!deadscope.can_publish(deadtoken),"scope owner lifetime expires safely");
  J output={{"status","passed"},{"check_count",checks},{"checks",results},{"scope","manufactured storage/phase/restart controls only; no fabricated positive motion; actual Hall joint integration is separately tested"},{"GPU",false}};std::ofstream(dir+"/full-time-storage-tests.json")<<output.dump(2)<<'\n';std::cout<<checks<<" full-time storage controls passed\n";return 0;}catch(const std::exception& x){std::cerr<<x.what()<<'\n';return 1;}}
